public void DeleteEmployeeByIds(List<Guid> ids, Guid userId)
{
    CheckDbConnect();
    var arr = ids.Select(x => "'" + x + "'").ToList();
    var idStr = string.Join("','", arr);
    Context.Database.ExecuteSqlCommand(
        "update Employees set Status = -1, UpdatedBy = '" + userId + "', UpdatedDate = getdate() " +
        "where Id in (" + idStr + ")");
    LogDelete("xóa nhân viên", "Employee", idStr);
}

public void RestoreEmployeeById(Guid id, Guid userId)
{
    CheckDbConnect();
    Context.Database.ExecuteSqlCommand(
        "update Employees set Status = 0, UpdatedBy = '" + userId + "', UpdatedDate = getdate() " +
        "where Id = '" + id + "' ");

    UpdateOrgTotalEmployee();

    LogDelete("phụ hồi dữ liệu nhân viên", "Employee", id.ToString());
}

public bool UpdateOrgTotalEmployee()
{
    try
    {
        CheckDbConnect();
        Context.Database.ExecuteSqlCommand("execute sp_UpdateOrgTotalEmployee");

        Caching.Delete("Organization", "general");
        Caching.Delete("EmployeeOrganization", "users");
        return true;
    }
    catch (Exception ex)
    {
        Console.WriteLine(ex.Message);
    }
    return false;
}

public void EmployeeUpdateInfo(EmployeeEditModel model)
{
    CheckDbConnect();
    var e = Context.Employees.FirstOrDefault(x => x.Id == model.Id);
    if (e != null)
    {
        e.FullName = model.FullName;
        e.Email = model.Email;
        e.UpdatedDate = DateTime.Now;
        Context.SaveChanges();
    }
}

